// src/context/contexts/index.ts
// Centralized export for all specialized context providers

export * from './WorkoutContext';
export * from './UserStatsContext';
export * from './GachaContext';
export * from './SegmentationContext';

// Re-export providers and hooks for convenience
export { 
  WorkoutProvider, 
  useWorkout 
} from './WorkoutContext';

export {
  UserStatsProvider,
  useUserStats
} from './UserStatsContext';

export {
  GachaProvider,
  useGacha
} from './GachaContext';

export {
  SegmentationProvider,
  useSegmentation  
} from './SegmentationContext';
